mapper.select:
select id, datasource_name as datasourceName, datasource_database as datasourceDatabase, datasource_type as datasourceType, datasource_host as datasourceHost, datasource_port as datasourcePort, datasource_user as datasourceUser, datasource_description as datasourceDescription, is_enabled as isEnabled, create_time as createTime, update_time as updateTime from datasource_config
datasource_name = #{datasourceName}
order by update_time desc
